    var attackable = BATTLE.phase === "act" && occ && u && occ.side !== u.side && inAttackRange(u, occ);
    var bg = occ ? (occ.side === "party" ? "#3f6b5c" : "#8c4a42") : (movable ? "#2c3e56" : "#171d28");
    if (attackable) bg = "#a3564f";
