function battleClick(e) {
  if (!BATTLE || BATTLE.over) return;
  var t = e.target.closest ? e.target.closest("[data-cell],[data-act],[data-target],[data-wait]") : e.target;
  if (!t || !t.getAttribute) return;
  if (BATTLE.type === "grid") {
    if (t.getAttribute("data-wait")) return gridPlayerWait();
    var cell = t.getAttribute("data-cell");
    if (!cell) return;
    var xy = cell.split(",").map(Number);
    if (BATTLE.phase === "move") {
      var unit = t.getAttribute("data-unit");
      var u = BATTLE.units[BATTLE.active];
      // clicking an adjacent enemy from move phase = move-in-place then attack
