    }
    if (BATTLE.phase === "act") {
      var unit2 = t.getAttribute("data-unit");
      if (unit2) return gridPlayerAttack(unit2);
    }
  } else {
    var act = t.getAttribute("data-act");
    if (act === "attack") { BATTLE.phase = "target"; return renderBattle(); }
    if (act === "item") return atbPlayerAct("item", t.getAttribute("data-t"));
    if (act === "defend") return atbPlayerAct("defend");
    var tgt = t.getAttribute("data-target");
    if (tgt) return atbPlayerAct("attack", tgt);
