}

// ---------------------------------------------------------------------------
// MENU SYSTEM  -- pause overlay bound to tables: status / inventory / save.
// Opened by action {action:"openMenu"} or the M key.
// ---------------------------------------------------------------------------
var MENU = null, menuEl = null;
function openMenu() { MENU = { tab: "status" }; renderMenu(); }
function closeMenu() { MENU = null; if (menuEl) menuEl.style.display = "none"; }
function renderMenu() {
  if (!MENU) return;
  if (!menuEl) {
    menuEl = document.createElement("div");
    menuEl.style.cssText = "position:absolute;inset:8px;background:rgba(10,14,20,.96);" +
      "border:1px solid #3f5c6b;border-radius:8px;padding:12px;color:#e8e2d0;" +
      "font-size:13px;overflow:auto;pointer-events:auto";
    hud.appendChild(menuEl);
  }
  var pl = nodes[playerId] || {};
  var h = '<div style="display:flex;gap:6px;margin-bottom:10px">';
  ["status", "items", "save"].forEach(function (tab) {
    h += '<div data-tab="' + tab + '" style="padding:5px 12px;border-radius:4px;cursor:pointer;background:' +
      (MENU.tab === tab ? "#3f5c6b" : "#171d28") + '">' + tab + "</div>";
  });
  h += '<div data-x="1" style="margin-left:auto;padding:5px 12px;background:#8c4a42;border-radius:4px;cursor:pointer">close</div></div>';

  if (MENU.tab === "status") {
    h += "<div>HP " + (pl.hp || 0) + "/" + (pl.maxHp || 0) + "</div>";
    h += "<div>Level " + playerLevel() + " &nbsp; XP " + (world.flags.xp || 0) + "</div>";
    h += "<div>Gold " + gold() + "</div>";
    h += "<div>ATK " + derivedStat((pl.stats && pl.stats.attack) || 0, "atk") +
      " &nbsp; DEF " + derivedStat(0, "def") + "</div>";
    var eq = Object.keys(INV.equipped).map(function (sl) { return __kvEsc(sl) + ": " + __kvEsc(itemDef(INV.equipped[sl]).name || INV.equipped[sl]); });
    if (eq.length) h += '<div style="margin-top:6px;color:#8a8a8a">' + eq.join(" · ") + "</div>";
  } else if (MENU.tab === "items") {
    var ids = Object.keys(INV.items);
    if (!ids.length) h += '<div style="color:#8a8a8a">Empty.</div>';
    ids.forEach(function (id) {
      var it = itemDef(id);
      h += '<div data-use="' + id + '" style="display:flex;justify-content:space-between;padding:6px 8px;' +
        'margin-top:4px;background:#1b2430;border-radius:4px;cursor:pointer">' +
        "<span>" + __kvEsc(it.name || id) + " x" + invCount(id) + "</span>" +
        '<span style="color:#8a8a8a;font-size:11px">' + (it.kind === "weapon" || it.kind === "trinket" ? "equip" : (it.heal ? "use" : "")) + "</span></div>";
    });
  } else if (MENU.tab === "save") {
    h += '<div data-save="1" style="padding:8px 12px;background:#3f6b5c;border-radius:4px;cursor:pointer;display:inline-block">Save progress</div>';
    if (MENU.saved) h += '<div style="margin-top:6px;color:#49c07a">Saved.</div>';
  }
  menuEl.innerHTML = h;
  menuEl.style.display = "block";
  menuEl.onclick = function (e) {
    var t = e.target.closest ? e.target.closest("[data-tab],[data-x],[data-use],[data-save]") : e.target;
    if (!t || !t.getAttribute) return;
    if (t.getAttribute("data-x")) return closeMenu();
    var tab = t.getAttribute("data-tab");
    if (tab) { MENU.tab = tab; MENU.saved = false; return renderMenu(); }
    var use = t.getAttribute("data-use");
    if (use) {
      var it = itemDef(use);
      var pl2 = nodes[playerId];
      if (it.kind === "weapon" || it.kind === "trinket") equip(it.kind === "weapon" ? "weapon" : "trinket", use);
      else if (it.heal && pl2) { invRemove(use, 1); pl2.hp = Math.min(pl2.maxHp || 999, (pl2.hp || 0) + it.heal); }
      return renderMenu();
    }
    if (t.getAttribute("data-save")) { bridgeCommit(); MENU.saved = true; return renderMenu(); }
  };
}

// ---------------------------------------------------------------------------
// v4: SHOOTER + STEALTH SET  -- projectiles, lock-on, vision cones, stimuli.
// ---------------------------------------------------------------------------

// ---- occluders: MeshInstances with collision block sight lines -------------
// ---------------------------------------------------------------------------
// PHYSICS (v6) -- Bullet-style rigid bodies. Fixed 60Hz substeps decoupled
// from render dt so simulation is deterministic; sequential impulse solver
// with Baumgarte positional correction; uniform-grid broadphase; bodies sleep.
// Declared per node:  physics: { body:"dynamic"|"static"|"kinematic",
//   shape:"sphere"|"box"|"capsule", radius, half:[x,y,z], height,
//   mass, restitution, friction, gravityScale }
// ---------------------------------------------------------------------------
var BODIES = [];
var PHYS = { gravity: -20, fixedDt: 1 / 60, accum: 0, maxSteps: 5, iterations: 12,
             sleepVel: 0.08, sleepTime: 0.5, slop: 0.01, baumgarte: 0.5, cell: 2.0 };
var PB_GROUND = { invMass: 0, vel: { x: 0, y: 0, z: 0 }, rest: 0, fric: 0.9, node: {} };

function physRegister(n) {
  var p = n.physics || {};
  n._pb = {
    node: n,
    kind: p.body || "dynamic",
    shape: p.shape || "sphere",
    r: p.radius != null ? p.radius : 0.4,
    half: p.half || [0.5, 0.5, 0.5],
    h: p.height != null ? p.height : 1.6,
    mass: (p.body === "static" || p.body === "kinematic") ? 0 : (p.mass != null ? p.mass : 1),
    rest: p.restitution != null ? p.restitution : 0.2,
    fric: p.friction != null ? p.friction : 0.5,
    gs: p.gravityScale != null ? p.gravityScale : 1,
    vel: { x: 0, y: 0, z: 0 },
    sleep: 0, asleep: false
  };
  n._pb.invMass = n._pb.mass > 0 ? 1 / n._pb.mass : 0;
  BODIES.push(n._pb);
}

function pbPos(b) {
  var t = b.node.transform || (b.node.transform = {});
  t.pos = t.pos || [0, 0, 0];
  return t.pos;
}
function pbWake(b) { b.asleep = false; b.sleep = 0; }
function physImpulse(n, x, y, z) {
  var b = n._pb; if (!b || b.invMass === 0) return;
  b.vel.x += x * b.invMass; b.vel.y += y * b.invMass; b.vel.z += z * b.invMass;
  pbWake(b);
}
function physSetVel(n, x, y, z) {
  var b = n._pb; if (!b) return;
  b.vel.x = x; b.vel.y = y; b.vel.z = z; pbWake(b);
}

// --- shape radius helpers (broadphase bound) -------------------------------
function pbBound(b) {
  if (b.shape === "box") return Math.sqrt(b.half[0]*b.half[0] + b.half[1]*b.half[1] + b.half[2]*b.half[2]);
  if (b.shape === "capsule") return b.r + b.h * 0.5;
  return b.r;
}

// --- narrowphase: returns { nx, ny, nz, depth } or null ---------------------
// Sphere/capsule treated as swept spheres on the Y axis; box uses closest-point.
// Axis-aligned box vs box: overlap on all three axes, separate along the
// axis of least penetration. Boxes do not rotate in this solver, which is
// period-correct and keeps the contact cheap.
function pbBoxBox(a, b) {
  var pa = pbPos(a), pb = pbPos(b);
  var dx = pb[0] - pa[0], ox = (a.half[0] + b.half[0]) - Math.abs(dx);
  if (ox <= 0) return null;
  var dy = pb[1] - pa[1], oy = (a.half[1] + b.half[1]) - Math.abs(dy);
  if (oy <= 0) return null;
  var dz = pb[2] - pa[2], oz = (a.half[2] + b.half[2]) - Math.abs(dz);
  if (oz <= 0) return null;
  if (oy <= ox && oy <= oz) return { nx: 0, ny: dy < 0 ? -1 : 1, nz: 0, depth: oy };
  if (ox <= oz) return { nx: dx < 0 ? -1 : 1, ny: 0, nz: 0, depth: ox };
  return { nx: 0, ny: 0, nz: dz < 0 ? -1 : 1, depth: oz };
}

function pbContact(a, b) {
  var pa = pbPos(a), pb = pbPos(b);
  var ax = pa[0], ay = pa[1], az = pa[2];
  var bx = pb[0], by = pb[1], bz = pb[2];

  if (a.shape === "box" && b.shape === "box") return pbBoxBox(a, b);
  if (a.shape === "box" || b.shape === "box") {
    var boxB = (b.shape === "box") ? b : a;
    var sph  = (b.shape === "box") ? a : b;
    var bp = pbPos(boxB), sp = pbPos(sph);
    var hx = boxB.half[0], hy = boxB.half[1], hz = boxB.half[2];
    var cx = Math.max(bp[0] - hx, Math.min(sp[0], bp[0] + hx));
    var cy = Math.max(bp[1] - hy, Math.min(sp[1], bp[1] + hy));
    var cz = Math.max(bp[2] - hz, Math.min(sp[2], bp[2] + hz));
    var dx = sp[0] - cx, dy = sp[1] - cy, dz = sp[2] - cz;
    var d2 = dx*dx + dy*dy + dz*dz;
    var sr = sph.shape === "capsule" ? sph.r : sph.r;
    if (d2 > sr * sr) return null;
    var d = Math.sqrt(d2);
    if (d < 1e-6) { dx = 0; dy = 1; dz = 0; d = 1; }
    var n = { nx: dx / d, ny: dy / d, nz: dz / d, depth: sr - d };
    if (boxB === b) return n;
    return { nx: -n.nx, ny: -n.ny, nz: -n.nz, depth: n.depth };
  }

  // sphere/capsule vs sphere/capsule: clamp Y onto each segment
  var ah = a.shape === "capsule" ? a.h * 0.5 : 0;
  var bh = b.shape === "capsule" ? b.h * 0.5 : 0;
  var ayc = Math.max(ay - ah, Math.min(by, ay + ah));
  var byc = Math.max(by - bh, Math.min(ayc, by + bh));
  var dx2 = bx - ax, dy2 = byc - ayc, dz2 = bz - az;
  var rr = a.r + b.r;
  var dd = dx2*dx2 + dy2*dy2 + dz2*dz2;
  if (dd > rr * rr) return null;
  var dl = Math.sqrt(dd);
  if (dl < 1e-6) { dx2 = 0; dy2 = 1; dz2 = 0; dl = 1; }
  return { nx: dx2 / dl, ny: dy2 / dl, nz: dz2 / dl, depth: rr - dl };
}

// --- broadphase: uniform grid on xz ----------------------------------------
function pbPairs() {
  var grid = {}, pairs = [], i, j;
  for (i = 0; i < BODIES.length; i++) {
    var b = BODIES[i];
    if (b.node._dead) continue;
    var p = pbPos(b), rad = pbBound(b);
    var x0 = Math.floor((p[0] - rad) / PHYS.cell), x1 = Math.floor((p[0] + rad) / PHYS.cell);
    var z0 = Math.floor((p[2] - rad) / PHYS.cell), z1 = Math.floor((p[2] + rad) / PHYS.cell);
    for (var gx = x0; gx <= x1; gx++) for (var gz = z0; gz <= z1; gz++) {
      var k = gx + ":" + gz;
      (grid[k] = grid[k] || []).push(i);
    }
  }
  var seen = {};
  for (var key in grid) {
    var cell = grid[key];
    for (i = 0; i < cell.length; i++) for (j = i + 1; j < cell.length; j++) {
      var A = BODIES[cell[i]], B = BODIES[cell[j]];
      if (A.invMass === 0 && B.invMass === 0) continue;
      if (A.asleep && B.asleep) continue;
      var pk = cell[i] < cell[j] ? cell[i] + "_" + cell[j] : cell[j] + "_" + cell[i];
      if (seen[pk]) continue;
      seen[pk] = 1;
      pairs.push([A, B]);
    }
  }
  return pairs;
}

// --- one fixed step --------------------------------------------------------
function physContacts() {
  var contacts = [], i, b;
  var pairs = pbPairs();
  for (i = 0; i < pairs.length; i++) {
    var c = pbContact(pairs[i][0], pairs[i][1]);
    if (c) { c.a = pairs[i][0]; c.b = pairs[i][1]; contacts.push(c); }
  }
  // The floor is a static contact so the solver, not a clamp, carries
  // resting weight. Included at touch distance (small negative depth) so the
  // velocity solve catches bodies the moment they land.
  for (i = 0; i < BODIES.length; i++) {
    b = BODIES[i];
    if (b.invMass === 0 || b.asleep || b.node._dead) continue;
    var gp = pbPos(b);
    var gfloor = terrainHeight(gp[0], gp[2]);
    var gfoot = b.shape === "box" ? b.half[1] : (b.shape === "capsule" ? b.h * 0.5 + b.r : b.r);
    var gd = (gfloor + gfoot) - gp[1];
    if (gd > -0.02) contacts.push({ a: PB_GROUND, b: b, nx: 0, ny: 1, nz: 0, depth: Math.max(gd, 0) });
  }
  contacts.sort(function (u, v) {
    var uy = Math.min(u.a.invMass === 0 ? -1e9 : pbPos(u.a)[1], u.b.invMass === 0 ? -1e9 : pbPos(u.b)[1]);
    var vy = Math.min(v.a.invMass === 0 ? -1e9 : pbPos(v.a)[1], v.b.invMass === 0 ? -1e9 : pbPos(v.b)[1]);
    return uy - vy;
  });
  return contacts;
}

// Inverse inertia for the body's shape. Spheres: 2/5 m r^2. Boxes: the
// principal diagonal of a cuboid tensor. Stored inverted so it multiplies.
// World-space corners of a rotated box body.
function pbCorners(b) {
  var hl = b.half || [0.5, 0.5, 0.5];
  var p = pbPos(b);
  var rt = (b.node.transform && b.node.transform.rot) || [0, 0, 0];
  var cx2 = Math.cos((rt[0] || 0) * DEG), sx2 = Math.sin((rt[0] || 0) * DEG);
  var cy2 = Math.cos((rt[1] || 0) * DEG), sy2 = Math.sin((rt[1] || 0) * DEG);
  var cz2 = Math.cos((rt[2] || 0) * DEG), sz2 = Math.sin((rt[2] || 0) * DEG);
  var out = [];
  for (var i = 0; i < 8; i++) {
    var lx = (i & 1 ? hl[0] : -hl[0]);
    var ly = (i & 2 ? hl[1] : -hl[1]);
    var lz = (i & 4 ? hl[2] : -hl[2]);
    var y1 = ly * cx2 - lz * sx2, z1 = ly * sx2 + lz * cx2;
    var x2 = lx * cy2 + z1 * sy2, z2 = -lx * sy2 + z1 * cy2;
    var x3 = x2 * cz2 - y1 * sz2, y3 = x2 * sz2 + y1 * cz2;
